    raise ValueError(f'Unknown: {kind}')

def checkout(total: int, discount_fn) -> int:
    return discount_fn(total)
print(checkout(100, lambda t: t - 10))

def test_divide_by_zero():
    try: divide(10, 0); assert False
    except ValueError: pass

class PayAdapter:
    def __init__(self, old): self.old = old
    def charge(self, c): return self.old.pay(c / 100)

class Cached:
    def __init__(self, f): self.f, self.c = f, {}
    def get(self, k): return self.c.setdefault(k, self.f(k))

listeners = []
def notify(evt):
    for fn in listeners: fn(evt)

